$prefix='gqa'.bin2hex(random_bytes(4));$passed=0;$owners=[];$failure=null;
function gcheck(bool $ok,string $label):void{global $passed;if(!$ok)throw new RuntimeException($label);$passed++;echo 'PASS '.$label."\n";}
function greject(callable $fn,string $label):void{try{$fn();}catch(InvalidArgumentException){gcheck(true,$label);return;}gcheck(false,$label);}
function ghttp(string $path,?array $body=null,string $token='',string $origin=''):array{$c=curl_init('http://localhost:8090'.$path);$headers=[];if($token)$headers[]='Cookie: token='.$token;if($origin)$headers[]='Origin: '.$origin;if($body!==null){$headers[]='Content-Type: application/json';curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body)]);}curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>$headers]);$raw=curl_exec($c);if($raw===false)throw new RuntimeException('Local HTTP request failed');$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);$status=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($status>=500)throw new RuntimeException('HTTP error '.strtok($path,'?'));return ['_status'=>$status,'_headers'=>substr($raw,0,$size)]+(json_decode(substr($raw,$size),true)?:['code'=>0]);}
