 foreach(['a','b']as $key){$account=$prefix.$key;$mid=Directory::saveMerchant(1,['name'=>$account,'account'=>$account,'password'=>'GeoLocal2026!']);$uid=(int)Db::name('oem_merchant')->where('id',$mid)->value('user_id');$owners[$key]=['mid'=>$mid,'uid'=>$uid,'account'=>$account];$r=ghttp('/api/merchant/login',['account'=>$account,'password'=>'GeoLocal2026!','scene'=>1,'terminal'=>4]);gcheck($r['code']===1,'isolated merchant login '.$key);$tokens[$key]=$r['data']['token'];}
 $a=$owners['a']['uid'];$b=$owners['b']['uid'];$api=fn($action,$p=null,$who='a')=>ghttp('/api/merchantGeo/'.$action,$p,$tokens[$who]);
 foreach(['summary','profile','lists?kind=questions']as $action)gcheck(ghttp('/api/merchantGeo/'.$action)['code']===-1,'guest read rejected '.$action);
 foreach(['save','profileSave','templates','toPress']as $action)gcheck(ghttp('/api/merchantGeo/'.$action,[])['code']===-1,'guest mutation rejected '.$action);
 $summary=$api('summary')['data'];gcheck($summary['questions']===0&&$summary['articles']===0&&$summary['evidence']===0&&!$summary['automatic_monitoring']&&!$summary['ai_generation'],'empty workspace has truthful counts and unavailable providers');
 $profile=['revision'=>0,'brand_name'=>'验收品牌','industry'=>'本地生活','intro'=>'实际公司介绍','website'=>'https://example.com'];gcheck($api('profileSave',$profile)['code']===1,'brand profile saved');gcheck($api('profile',null,'b')['data']['brand_name']==='','merchant brand profiles isolated');gcheck($api('profileSave',$profile)['code']!==1,'stale brand write rejected');
 gcheck(ghttp('/api/merchantGeo/profileSave',$profile,$tokens['a'],'https://example.com')['code']!==1,'cross origin profile mutation denied');gcheck($api('profileSave')['code']!==1,'GET cannot change brand profile');
 gcheck($api('templates',[])['data']['created']===5&&$api('templates',[])['data']['created']===0,'local question templates persist idempotently');
 $q=$api('lists?kind=questions')['data'];gcheck($q['count']===5&&$q['lists'][0]['source']==='local_template','question provenance stored as local template');gcheck($api('lists?kind=questions',null,'b')['data']['count']===0,'questions scoped to merchant');
 $qid=$q['lists'][0]['id'];gcheck($api('save',['kind'=>'questions','id'=>$qid,'question'=>'越权修改'],'b')['code']!==1,'foreign question edit denied');
 $r=$api('save',['kind'=>'articles','title'=>'GEO QA <标题>','content'=>'<script>QA</script> 正文','question'=>'真实客户问题']);gcheck($r['code']===1,'article draft saved');$article=(int)$r['data']['id'];
 gcheck($api('lists?kind=articles',null,'b')['data']['count']===0,'article list scoped');gcheck($api('save',['kind'=>'articles','id'=>$article,'title'=>'forged','content'=>'forged'],'b')['code']!==1,'foreign article edit denied');
 gcheck($api('toPress',['id'=>$article],'b')['code']!==1,'foreign article cannot create press draft');$draft=$api('toPress',['id'=>$article]);gcheck($draft['code']===1,'owned article becomes press draft');$draftId=(int)$draft['data']['draft_id'];gcheck($api('toPress',['id'=>$article])['data']['draft_id']===$draftId,'same article version does not duplicate press drafts');
 $stored=Db::name('press_draft')->where('id',$draftId)->find();gcheck((int)$stored['user_id']===$a&&$stored['body']==='<script>QA</script> 正文','press draft retains owned immutable content');
 $api('save',['kind'=>'articles','id'=>$article,'title'=>'GEO QA <标题>','content'=>'新版本']);gcheck($api('toPress',['id'=>$article])['data']['draft_id']!==$draftId&&Db::name('press_draft')->where('id',$draftId)->value('body')==='<script>QA</script> 正文','editing content creates a new immutable press version');
 $evidence=['kind'=>'evidence','platform'=>'豆包','question'=>'QA问题','answer'=>'我实际看到的回答原文','url'=>'https://example.com/answer','observed_at'=>time()-60];gcheck($api('save',$evidence)['code']===1,'manual evidence saved');
 gcheck($api('save',array_replace($evidence,['url'=>'javascript:alert(1)']))['code']!==1,'unsafe evidence URL denied');gcheck($api('save',array_replace($evidence,['observed_at'=>time()+600]))['code']!==1,'future observation time denied');
 $rows=$api('lists?kind=evidence')['data']['lists'];gcheck(count($rows)===1&&$rows[0]['status']==='recorded_manual'&&(int)$rows[0]['rank_value']===0&&(int)$rows[0]['mentioned']===0,'manual evidence does not invent ranking or brand mentions');gcheck($api('lists?kind=evidence',null,'b')['data']['count']===0,'evidence scoped to merchant');
 $summary=$api('summary')['data'];gcheck($summary['questions']===5&&$summary['articles']===1&&$summary['evidence']===1,'summary derived from persisted scoped records');gcheck($api('summary',null,'b')['data']['articles']===0,'foreign merchant summary excludes records');
 greject(fn()=>Geo::lists(999999,$a,['kind'=>'articles']),'forged tenant cannot reuse user identity');greject(fn()=>Geo::toPress(1,$b,$article),'service enforces ownership before draft creation');
 gcheck(Db::name('user')->where('id',$a)->value('user_money')==='0.00'&&Db::name('press_order')->where(['tenant_id'=>1,'user_id'=>$a])->count()===0,'GEO preparation does not charge or place media orders');
 $old=ghttp('/app/aigc_geo/console',null,$tokens['a']);gcheck($old['_status']===302&&str_contains($old['_headers'],'/ai/geo'),'legacy demo console redirects to real workspace');
}catch(Throwable $e){$failure=$e;}finally{
